import type { MetadataRoute } from "next";

/**
 * Installability requires a manifest plus a service worker (see
 * components/pwa/service-worker-registration.tsx). Icons are generated by
 * scripts/generate-icons.mjs — regenerate rather than hand-editing those files.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Sudoku",
    short_name: "Sudoku",
    description: "Generate and play 9x9 sudoku puzzles",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: "#f4f7fc",
    // Matches --background in globals.css. Android tints the status bar and the
    // splash screen from this.
    theme_color: "#2a55d4",
    icons: [
      {
        src: "/icon-192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icon-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
      // Android crops maskable icons to whatever shape the launcher uses, so the
      // art has to survive a circle as well as a squircle. These keep the board
      // inside the safe zone; see the generator for the geometry.
      {
        src: "/icon-maskable-192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "maskable",
      },
      {
        src: "/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}